            rate.setClaimsAfter(r.claimsAfter());
            rate.setEarlier(r.earlier().stream()
                    .map(v -> new RateVersion(null, v.version(), v.rate(), v.to(), v.claimsAfter())).toList());
            return rate;
        }).toList();
